-- Review-only proposal identity/history and version-3 rental guard.
-- Generated by `supabase migration new luxor_proposal_family_history_v3`.
-- This migration is intentionally not applied by this change.

alter table public.luxor_invoices
  add column if not exists proposal_family_id uuid,
  add column if not exists proposal_number integer,
  add column if not exists proposal_first_sent_at timestamptz,
  add column if not exists proposal_latest_sent_at timestamptz;

create table if not exists public.luxor_proposal_families (
  id uuid primary key,
  inquiry_id uuid not null references public.luxor_inquiries(id) on delete cascade,
  proposal_number integer,
  first_sent_at timestamptz,
  latest_sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint luxor_proposal_families_number_check check (proposal_number is null or proposal_number > 0),
  constraint luxor_proposal_families_send_times_check check (
    (proposal_number is null and first_sent_at is null and latest_sent_at is null)
    or (proposal_number is not null and first_sent_at is not null and latest_sent_at is not null and latest_sent_at >= first_sent_at)
  )
);

-- The root invoice ID is the stable family identity. Existing revision links
-- are followed to their root; only recorded proposal_sent_at values are used.
with recursive invoice_chain as (
  select i.id as start_id, i.inquiry_id, i.id as current_id, i.supersedes_invoice_id,
         array[i.id]::uuid[] as path
  from public.luxor_invoices i
  where i.invoice_kind = 'event' and i.inquiry_id is not null
  union all
  select c.start_id, c.inquiry_id, parent.id, parent.supersedes_invoice_id,
         c.path || parent.id
  from invoice_chain c
  join public.luxor_invoices parent on parent.id = c.supersedes_invoice_id
    and parent.inquiry_id = c.inquiry_id and parent.invoice_kind = 'event'
  where not parent.id = any(c.path)
), roots as (
  select distinct on (start_id) start_id, inquiry_id, current_id as family_id
  from invoice_chain
  order by start_id, cardinality(path) desc
), family_sends as (
  select r.family_id, r.inquiry_id,
         min(i.proposal_sent_at) filter (where i.proposal_sent_at is not null) as first_sent_at,
         max(i.proposal_sent_at) filter (where i.proposal_sent_at is not null) as latest_sent_at,
         min(i.created_at) as created_at
  from roots r
  join public.luxor_invoices i on i.id = r.start_id
  group by r.family_id, r.inquiry_id
), numbered as (
  select f.*,
         case when f.first_sent_at is null then null else
           row_number() over (partition by f.inquiry_id order by f.first_sent_at, f.created_at, f.family_id)::integer
         end as proposal_number
  from family_sends f
)
insert into public.luxor_proposal_families(id, inquiry_id, proposal_number, first_sent_at, latest_sent_at, created_at, updated_at)
select family_id, inquiry_id, proposal_number, first_sent_at, latest_sent_at, created_at, now()
from numbered
on conflict (id) do nothing;

with recursive invoice_chain as (
  select i.id as start_id, i.inquiry_id, i.id as current_id, i.supersedes_invoice_id,
         array[i.id]::uuid[] as path
  from public.luxor_invoices i
  where i.invoice_kind = 'event' and i.inquiry_id is not null
  union all
  select c.start_id, c.inquiry_id, parent.id, parent.supersedes_invoice_id,
         c.path || parent.id
  from invoice_chain c
  join public.luxor_invoices parent on parent.id = c.supersedes_invoice_id
    and parent.inquiry_id = c.inquiry_id and parent.invoice_kind = 'event'
  where not parent.id = any(c.path)
), roots as (
  select distinct on (start_id) start_id, current_id as family_id
  from invoice_chain
  order by start_id, cardinality(path) desc
)
update public.luxor_invoices i
set proposal_family_id = r.family_id,
    proposal_number = f.proposal_number,
    proposal_first_sent_at = f.first_sent_at,
    proposal_latest_sent_at = f.latest_sent_at
from roots r
join public.luxor_proposal_families f on f.id = r.family_id
where i.id = r.start_id;

alter table public.luxor_invoices
  add constraint luxor_invoices_proposal_number_check check (proposal_number is null or proposal_number > 0);
alter table public.luxor_invoices
  add constraint luxor_invoices_proposal_family_fk foreign key (proposal_family_id)
  references public.luxor_proposal_families(id) on delete set null;
create index if not exists luxor_invoices_proposal_family_idx
  on public.luxor_invoices(proposal_family_id, created_at);
create unique index if not exists luxor_proposal_families_inquiry_number_idx
  on public.luxor_proposal_families(inquiry_id, proposal_number) where proposal_number is not null;

create table if not exists public.luxor_proposal_send_attempts (
  id uuid primary key,
  proposal_family_id uuid not null references public.luxor_proposal_families(id) on delete restrict,
  invoice_id uuid not null references public.luxor_invoices(id) on delete restrict,
  inquiry_id uuid not null references public.luxor_inquiries(id) on delete restrict,
  attempt_number integer not null check (attempt_number > 0),
  proposed_number integer not null check (proposed_number > 0),
  channel text not null check (channel in ('email', 'in_person')),
  provider text,
  idempotency_key text not null unique,
  state text not null check (state in ('preparing', 'sending', 'delivery_unconfirmed', 'sent', 'failed', 'delivered', 'bounced')),
  recipient_email text,
  actor_email text,
  provider_message_id text,
  started_at timestamptz not null default now(),
  sent_at timestamptz,
  delivery_confirmed_at timestamptz,
  failed_at timestamptz,
  failure_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint luxor_proposal_send_attempts_receipt_check check (
    state not in ('sent', 'delivered', 'bounced') or sent_at is not null
  )
);
create unique index if not exists luxor_proposal_send_attempts_pending_lead_idx
  on public.luxor_proposal_send_attempts(inquiry_id)
  where state in ('preparing', 'sending', 'delivery_unconfirmed');
create unique index if not exists luxor_proposal_send_attempts_provider_id_idx
  on public.luxor_proposal_send_attempts(provider, provider_message_id)
  where provider_message_id is not null;
create index if not exists luxor_proposal_send_attempts_family_date_idx
  on public.luxor_proposal_send_attempts(proposal_family_id, started_at desc);

create table if not exists public.luxor_proposal_activity (
  id bigint generated always as identity primary key,
  proposal_family_id uuid not null references public.luxor_proposal_families(id) on delete restrict,
  invoice_id uuid references public.luxor_invoices(id) on delete set null,
  inquiry_id uuid not null references public.luxor_inquiries(id) on delete restrict,
  event_type text not null check (event_type in (
    'created', 'edited', 'send_started', 'send_failed', 'sent', 'resent',
    'delivered', 'viewed', 'accepted', 'declined', 'expired', 'superseded'
  )),
  actor_type text not null check (actor_type in ('administrator', 'customer', 'provider', 'system')),
  actor_email text,
  recipient_email text,
  provider text,
  provider_message_id text,
  occurred_at timestamptz not null default now(),
  activity_key text unique,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists luxor_proposal_activity_family_date_idx
  on public.luxor_proposal_activity(proposal_family_id, occurred_at desc, id desc);
create index if not exists luxor_proposal_activity_invoice_date_idx
  on public.luxor_proposal_activity(invoice_id, occurred_at desc) where invoice_id is not null;

alter table public.luxor_proposal_families enable row level security;
alter table public.luxor_proposal_send_attempts enable row level security;
alter table public.luxor_proposal_activity enable row level security;
revoke all on public.luxor_proposal_families, public.luxor_proposal_send_attempts, public.luxor_proposal_activity from public, anon, authenticated;
grant select, insert, update, delete on public.luxor_proposal_families, public.luxor_proposal_send_attempts to service_role;
grant select, insert on public.luxor_proposal_activity to service_role;
grant usage, select on sequence public.luxor_proposal_activity_id_seq to service_role;

create or replace function public.luxor_reject_proposal_activity_mutation()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  raise exception 'Proposal activity history is append-only.' using errcode = '42501';
end;
$$;
create trigger luxor_proposal_activity_append_only
before update or delete on public.luxor_proposal_activity
for each row execute function public.luxor_reject_proposal_activity_mutation();

create or replace function public.luxor_assign_proposal_family()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare
  family public.luxor_proposal_families%rowtype;
  parent_family_id uuid;
begin
  if new.invoice_kind is distinct from 'event' or new.inquiry_id is null then
    if new.proposal_family_id is not null or new.proposal_number is not null then
      raise exception 'Proposal identity is available only for a lead event proposal.' using errcode = '23514';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' and old.inquiry_id is distinct from new.inquiry_id then
    raise exception 'A proposal cannot be moved to another lead.' using errcode = '23514';
  end if;
  if new.supersedes_invoice_id is not null then
    select i.proposal_family_id into parent_family_id
    from public.luxor_invoices i
    where i.id = new.supersedes_invoice_id and i.inquiry_id = new.inquiry_id and i.invoice_kind = 'event';
    if parent_family_id is null then
      raise exception 'A proposal revision must reference an event proposal for the same lead.' using errcode = '23503';
    end if;
    if new.proposal_family_id is not null and new.proposal_family_id is distinct from parent_family_id then
      raise exception 'A proposal revision cannot change proposal family.' using errcode = '23514';
    end if;
    new.proposal_family_id := parent_family_id;
  elsif new.proposal_family_id is null then
    new.proposal_family_id := new.id;
    insert into public.luxor_proposal_families(id, inquiry_id)
    values (new.proposal_family_id, new.inquiry_id)
    on conflict (id) do nothing;
  end if;
  select * into family from public.luxor_proposal_families f
  where f.id = new.proposal_family_id for update;
  if not found or family.inquiry_id is distinct from new.inquiry_id then
    raise exception 'Proposal family does not belong to this lead.' using errcode = '23503';
  end if;
  if new.proposal_number is not null and new.proposal_number is distinct from family.proposal_number then
    raise exception 'Proposal numbers are assigned by the first successful send.' using errcode = '23514';
  end if;
  new.proposal_number := family.proposal_number;
  new.proposal_first_sent_at := family.first_sent_at;
  new.proposal_latest_sent_at := family.latest_sent_at;
  return new;
end;
$$;
create trigger a_luxor_assign_proposal_family
before insert or update of invoice_kind, inquiry_id, supersedes_invoice_id, proposal_family_id, proposal_number
on public.luxor_invoices for each row execute function public.luxor_assign_proposal_family();

create or replace function public.luxor_append_proposal_activity(
  p_invoice_id uuid,
  p_event_type text,
  p_actor_type text default 'system',
  p_actor_email text default null,
  p_recipient_email text default null,
  p_provider text default null,
  p_provider_message_id text default null,
  p_occurred_at timestamptz default now(),
  p_activity_key text default null,
  p_details jsonb default '{}'::jsonb
) returns bigint language plpgsql security invoker set search_path = '' as $$
declare
  invoice public.luxor_invoices%rowtype;
  activity_id bigint;
begin
  select i.* into invoice from public.luxor_invoices i where i.id = p_invoice_id;
  if not found or invoice.invoice_kind is distinct from 'event' or invoice.proposal_family_id is null then
    raise exception 'A saved lead proposal is required for activity history.' using errcode = 'P0001';
  end if;
  insert into public.luxor_proposal_activity(
    proposal_family_id, invoice_id, inquiry_id, event_type, actor_type,
    actor_email, recipient_email, provider, provider_message_id,
    occurred_at, activity_key, details
  ) values (
    invoice.proposal_family_id, invoice.id, invoice.inquiry_id, p_event_type,
    p_actor_type, nullif(left(p_actor_email, 320), ''), nullif(left(p_recipient_email, 320), ''),
    nullif(left(p_provider, 40), ''), nullif(left(p_provider_message_id, 500), ''),
    coalesce(p_occurred_at, now()), p_activity_key,
    case when jsonb_typeof(p_details) = 'object' then p_details else '{}'::jsonb end
  ) on conflict (activity_key) do nothing returning id into activity_id;
  return activity_id;
end;
$$;

create or replace function public.luxor_proposal_activity_trigger()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  if tg_op = 'INSERT' and new.invoice_kind = 'event' and new.proposal_family_id is not null then
    insert into public.luxor_proposal_activity(proposal_family_id, invoice_id, inquiry_id, event_type, actor_type, occurred_at, details)
    values (new.proposal_family_id, new.id, new.inquiry_id,
      case when new.supersedes_invoice_id is null then 'created' else 'created' end,
      'system', coalesce(new.created_at, now()),
      jsonb_build_object('revision', new.supersedes_invoice_id is not null, 'supersedes_invoice_id', new.supersedes_invoice_id));
  elsif tg_op = 'UPDATE' and old.proposal_accepted_at is null and new.proposal_accepted_at is not null then
    perform public.luxor_append_proposal_activity(new.id, 'accepted', 'customer', null, null, null, null, new.proposal_accepted_at,
      'accepted:' || new.id::text, jsonb_build_object('proposal_number', new.proposal_number));
  elsif tg_op = 'UPDATE' and new.offer_status = 'withdrawn' and old.offer_status is distinct from new.offer_status
     and exists (select 1 from public.luxor_invoices child where child.supersedes_invoice_id = new.id and child.invoice_kind = 'event') then
    perform public.luxor_append_proposal_activity(new.id, 'superseded', 'system', null, null, null, null, now(),
      'superseded:' || new.id::text, jsonb_build_object('replaced_by_invoice_id', (select child.id from public.luxor_invoices child where child.supersedes_invoice_id = new.id and child.invoice_kind = 'event' order by child.created_at desc limit 1)));
  end if;
  return new;
end;
$$;
create trigger luxor_proposal_activity_after_insert
after insert on public.luxor_invoices for each row execute function public.luxor_proposal_activity_trigger();
create trigger luxor_proposal_activity_after_update
after update of proposal_accepted_at, offer_status on public.luxor_invoices for each row execute function public.luxor_proposal_activity_trigger();

create or replace function public.luxor_begin_proposal_send(
  p_invoice_id uuid,
  p_attempt_id uuid,
  p_channel text,
  p_provider text,
  p_recipient_email text,
  p_actor_email text
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  invoice public.luxor_invoices%rowtype;
  family public.luxor_proposal_families%rowtype;
  attempt public.luxor_proposal_send_attempts%rowtype;
  proposed_number integer;
  next_attempt integer;
  attempt_key text;
begin
  select i.* into invoice from public.luxor_invoices i where i.id = p_invoice_id for update;
  if not found or invoice.invoice_kind is distinct from 'event' or invoice.inquiry_id is null
     or invoice.proposal_family_id is null then
    raise exception 'A saved event proposal for a lead is required.' using errcode = 'P0001';
  end if;
  perform 1 from public.luxor_inquiries q where q.id = invoice.inquiry_id for update;
  if not found then raise exception 'The proposal lead no longer exists.' using errcode = 'P0001'; end if;
  select * into family from public.luxor_proposal_families f where f.id = invoice.proposal_family_id for update;
  if not found or family.inquiry_id is distinct from invoice.inquiry_id then
    raise exception 'The proposal family does not match its lead.' using errcode = 'P0001';
  end if;
  select * into attempt from public.luxor_proposal_send_attempts a where a.id = p_attempt_id for update;
  if found then
    if attempt.invoice_id is distinct from invoice.id or attempt.proposal_family_id is distinct from family.id then
      raise exception 'The send attempt belongs to a different proposal.' using errcode = 'P0001';
    end if;
    return jsonb_build_object('attempt_id', attempt.id, 'proposal_number', attempt.proposed_number,
      'proposal_label', case when attempt.proposed_number = 1 then 'Proposal' else 'Proposal #' || attempt.proposed_number::text end,
      'idempotency_key', attempt.idempotency_key, 'state', attempt.state);
  end if;
  if invoice.proposal_accepted_at is not null or invoice.booking_id is not null or invoice.status = 'cancelled'
     or invoice.offer_status = 'withdrawn' then
    raise exception 'An accepted or withdrawn proposal cannot be sent.' using errcode = 'P0001';
  end if;
  select * into attempt from public.luxor_proposal_send_attempts a
  where a.inquiry_id = invoice.inquiry_id and a.state in ('preparing', 'sending', 'delivery_unconfirmed')
  order by a.started_at desc limit 1 for update;
  if found then
    if attempt.invoice_id = invoice.id then
      return jsonb_build_object('attempt_id', attempt.id, 'proposal_number', attempt.proposed_number,
        'proposal_label', case when attempt.proposed_number = 1 then 'Proposal' else 'Proposal #' || attempt.proposed_number::text end,
        'idempotency_key', attempt.idempotency_key, 'state', attempt.state);
    end if;
    raise exception 'Another proposal for this lead is currently being sent or needs delivery review.' using errcode = 'P0001';
  end if;
  proposed_number := coalesce(family.proposal_number,
    (select coalesce(max(f.proposal_number), 0) + 1 from public.luxor_proposal_families f where f.inquiry_id = invoice.inquiry_id));
  select coalesce(max(a.attempt_number), 0) + 1 into next_attempt
  from public.luxor_proposal_send_attempts a where a.proposal_family_id = family.id;
  attempt_key := 'proposal/' || invoice.id::text || '/' || coalesce(invoice.proposal_version, 1)::text || '/' || p_attempt_id::text;
  insert into public.luxor_proposal_send_attempts(
    id, proposal_family_id, invoice_id, inquiry_id, attempt_number, proposed_number,
    channel, provider, idempotency_key, state, recipient_email, actor_email
  ) values (
    p_attempt_id, family.id, invoice.id, invoice.inquiry_id, next_attempt, proposed_number,
    p_channel, p_provider, attempt_key, 'preparing', nullif(left(p_recipient_email, 320), ''), nullif(left(p_actor_email, 320), '')
  ) returning * into attempt;
  perform public.luxor_append_proposal_activity(invoice.id, 'send_started', 'administrator', p_actor_email,
    p_recipient_email, p_provider, null, attempt.started_at, 'send-started:' || attempt.id::text,
    jsonb_build_object('channel', p_channel, 'attempt_number', attempt.attempt_number, 'proposal_number', proposed_number));
  return jsonb_build_object('attempt_id', attempt.id, 'proposal_number', proposed_number,
    'proposal_label', case when proposed_number = 1 then 'Proposal' else 'Proposal #' || proposed_number::text end,
    'idempotency_key', attempt.idempotency_key, 'state', attempt.state);
end;
$$;

create or replace function public.luxor_complete_proposal_send(
  p_attempt_id uuid,
  p_provider_message_id text,
  p_sent_at timestamptz default now()
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  attempt public.luxor_proposal_send_attempts%rowtype;
  family public.luxor_proposal_families%rowtype;
  invoice public.luxor_invoices%rowtype;
  v_sent_at timestamptz := coalesce(p_sent_at, now());
  event_type text;
begin
  select * into attempt from public.luxor_proposal_send_attempts a where a.id = p_attempt_id for update;
  if not found then raise exception 'Proposal send attempt not found.' using errcode = 'P0001'; end if;
  select * into invoice from public.luxor_invoices i where i.id = attempt.invoice_id for update;
  if not found then raise exception 'Proposal no longer exists.' using errcode = 'P0001'; end if;
  if attempt.state in ('sent', 'delivered', 'bounced') then return to_jsonb(invoice); end if;
  if attempt.state not in ('preparing', 'sending', 'delivery_unconfirmed') then
    raise exception 'Only an active proposal send can be completed.' using errcode = 'P0001';
  end if;
  select * into family from public.luxor_proposal_families f where f.id = attempt.proposal_family_id for update;
  if not found then raise exception 'Proposal family not found.' using errcode = 'P0001'; end if;
  if family.proposal_number is null then
    update public.luxor_proposal_families f set proposal_number = attempt.proposed_number,
      first_sent_at = v_sent_at, latest_sent_at = v_sent_at, updated_at = now()
    where f.id = family.id and f.proposal_number is null;
  elsif family.proposal_number is distinct from attempt.proposed_number then
    raise exception 'Proposal numbering changed during send; delivery needs review.' using errcode = 'P0001';
  else
    update public.luxor_proposal_families f set latest_sent_at = greatest(coalesce(f.latest_sent_at, v_sent_at), v_sent_at), updated_at = now()
    where f.id = family.id;
  end if;
  select * into family from public.luxor_proposal_families f where f.id = attempt.proposal_family_id;
  update public.luxor_invoices i set
    proposal_number = family.proposal_number,
    proposal_first_sent_at = family.first_sent_at,
    proposal_latest_sent_at = family.latest_sent_at
  where i.proposal_family_id = family.id;
  update public.luxor_invoices i set status = 'sent', proposal_sent_at = v_sent_at,
    proposal_first_sent_at = family.first_sent_at, proposal_latest_sent_at = v_sent_at,
    proposal_number = family.proposal_number, updated_at = greatest(i.updated_at, v_sent_at)
  where i.id = invoice.id returning i.* into invoice;
  update public.luxor_proposal_send_attempts a set state = 'sent', sent_at = v_sent_at,
    provider_message_id = nullif(left(p_provider_message_id, 500), ''), updated_at = now()
  where a.id = attempt.id returning * into attempt;
  event_type := case when attempt.attempt_number > 1 or family.first_sent_at < v_sent_at then 'resent' else 'sent' end;
  perform public.luxor_append_proposal_activity(invoice.id, event_type, 'administrator', attempt.actor_email,
    attempt.recipient_email, attempt.provider, attempt.provider_message_id, v_sent_at,
    'send-completed:' || attempt.id::text,
    jsonb_build_object('attempt_id', attempt.id, 'proposal_number', family.proposal_number,
      'proposal_version', invoice.proposal_version, 'channel', attempt.channel));
  return to_jsonb(invoice);
end;
$$;

create or replace function public.luxor_mark_proposal_send_attempt_sending(p_attempt_id uuid)
returns boolean language plpgsql security invoker set search_path = '' as $$
begin
  update public.luxor_proposal_send_attempts a set state = 'sending', updated_at = now()
  where a.id = p_attempt_id and a.state in ('preparing', 'sending', 'delivery_unconfirmed');
  return found;
end;
$$;

create or replace function public.luxor_fail_proposal_send(
  p_attempt_id uuid,
  p_failure_reason text,
  p_delivery_unconfirmed boolean default false,
  p_failed_at timestamptz default now()
) returns boolean language plpgsql security invoker set search_path = '' as $$
declare
  attempt public.luxor_proposal_send_attempts%rowtype;
begin
  select * into attempt from public.luxor_proposal_send_attempts a where a.id = p_attempt_id for update;
  if not found or attempt.state in ('sent', 'delivered', 'bounced') then return false; end if;
  update public.luxor_proposal_send_attempts a set
    -- Once marked sending, a crash/error cannot prove that the provider did
    -- not accept the message. Retain the reservation and its idempotency key.
    state = case when p_delivery_unconfirmed or attempt.state = 'sending' then 'delivery_unconfirmed' else 'failed' end,
    failed_at = case when p_delivery_unconfirmed or attempt.state = 'sending' then null else coalesce(p_failed_at, now()) end,
    failure_reason = left(coalesce(p_failure_reason, 'Delivery failed.'), 1000), updated_at = now()
  where a.id = attempt.id;
  perform public.luxor_append_proposal_activity(attempt.invoice_id,
    case when p_delivery_unconfirmed then 'send_failed' else 'send_failed' end,
    'administrator', attempt.actor_email, attempt.recipient_email, attempt.provider,
    attempt.provider_message_id, coalesce(p_failed_at, now()), 'send-failed:' || attempt.id::text,
    jsonb_build_object('attempt_id', attempt.id, 'delivery_unconfirmed', p_delivery_unconfirmed or attempt.state = 'sending',
      'failure_reason', left(coalesce(p_failure_reason, 'Delivery failed.'), 1000)));
  return true;
end;
$$;

create or replace function public.luxor_record_proposal_delivery_event(
  p_provider_message_id text,
  p_event_type text,
  p_occurred_at timestamptz,
  p_provider_event_id text
) returns boolean language plpgsql security invoker set search_path = '' as $$
declare
  attempt public.luxor_proposal_send_attempts%rowtype;
  activity_type text;
  next_state text;
begin
  select * into attempt from public.luxor_proposal_send_attempts a
  where a.provider = 'resend' and a.provider_message_id = p_provider_message_id for update;
  if not found then return false; end if;
  if p_event_type = 'email.delivered' then
    next_state := 'delivered'; activity_type := 'delivered';
  elsif p_event_type = 'email.bounced' then
    next_state := 'bounced'; activity_type := 'send_failed';
  else
    return false;
  end if;
  update public.luxor_proposal_send_attempts a set state = next_state,
    delivery_confirmed_at = case when next_state = 'delivered' then coalesce(a.delivery_confirmed_at, p_occurred_at) else a.delivery_confirmed_at end,
    failure_reason = case when next_state = 'bounced' then 'Provider reported a bounce.' else a.failure_reason end,
    updated_at = now()
  where a.id = attempt.id and a.state not in ('delivered', 'bounced');
  if found then
    perform public.luxor_append_proposal_activity(attempt.invoice_id, activity_type, 'provider', null,
      attempt.recipient_email, attempt.provider, p_provider_message_id, p_occurred_at,
      'provider:' || p_provider_event_id,
      jsonb_build_object('provider_event_type', p_event_type, 'provider_event_id', p_provider_event_id));
  end if;
  return found;
end;
$$;

create or replace function public.luxor_record_proposal_view(
  p_invoice_id uuid,
  p_public_token uuid,
  p_viewed_at timestamptz default now()
) returns boolean language plpgsql security invoker set search_path = '' as $$
declare
  invoice public.luxor_invoices%rowtype;
  first_view boolean;
begin
  select * into invoice from public.luxor_invoices i where i.id = p_invoice_id for update;
  if not found or invoice.public_token is distinct from p_public_token or invoice.invoice_kind is distinct from 'event'
     or invoice.status is distinct from 'sent' or invoice.price_locked_at is null then
    raise exception 'A customer-facing published proposal is required.' using errcode = 'P0001';
  end if;
  first_view := invoice.proposal_viewed_at is null;
  update public.luxor_invoices i set proposal_viewed_at = coalesce(i.proposal_viewed_at, p_viewed_at),
    updated_at = greatest(i.updated_at, coalesce(p_viewed_at, now())) where i.id = invoice.id;
  perform public.luxor_append_proposal_activity(invoice.id, 'viewed', 'customer', null, null, null, null,
    coalesce(p_viewed_at, now()), 'customer-view:' || invoice.id::text || ':' || date_trunc('minute', coalesce(p_viewed_at, now()))::text,
    jsonb_build_object('proposal_number', invoice.proposal_number, 'first_view', first_view));
  return first_view;
end;
$$;

create or replace function public.luxor_guard_single_accepted_proposal_per_event()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare
  scope_key text;
begin
  if tg_op <> 'UPDATE' or old.proposal_accepted_at is not null or new.proposal_accepted_at is null
     or new.invoice_kind is distinct from 'event' or new.inquiry_id is null then return new; end if;
  -- The advisory lock only makes the following conflict query reliable when
  -- each statement gets a fresh snapshot after waiting for a concurrent accept.
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'LUXOR_PROPOSAL_ALTERNATE_ACCEPTED: Proposal acceptance requires READ COMMITTED isolation.' using errcode = 'P0001';
  end if;
  scope_key := new.inquiry_id::text || ':' || coalesce(new.lead_event_id::text, 'primary');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(scope_key, 87211));
  if exists (select 1 from public.luxor_invoices i
      where i.inquiry_id = new.inquiry_id and i.lead_event_id is not distinct from new.lead_event_id
        and i.invoice_kind = 'event' and i.id is distinct from new.id and i.proposal_accepted_at is not null) then
    raise exception 'LUXOR_PROPOSAL_ALTERNATE_ACCEPTED: Another proposal for this event has already been accepted.' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger a_luxor_guard_single_accepted_proposal
before update of proposal_accepted_at on public.luxor_invoices
for each row execute function public.luxor_guard_single_accepted_proposal_per_event();

create or replace function public.luxor_validate_weekday_rental_context(p_context jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  s jsonb := p_context -> 'weekday_custom_rental';
  policy jsonb;
  field text;
  event_day date;
  first_min integer;
  last_min integer;
  duration_min integer;
  increment_min integer;
  arrival_min integer;
  event_end_min integer;
  expected_total numeric;
begin
  if s is null then return null; end if;
  if jsonb_typeof(s) is distinct from 'object'
     or jsonb_typeof(s -> 'version') is distinct from 'number'
     or s -> 'version' not in ('1'::jsonb, '2'::jsonb, '3'::jsonb)
     or s ->> 'time_zone' is distinct from 'America/Chicago' then
    raise exception 'LUXOR_WEEKDAY_INVALID: Invalid saved rental snapshot.' using errcode = 'P0001';
  end if;
  foreach field in array array['duration_minutes', 'duration_hours', 'hourly_rate', 'rental_total', 'minimum_hours', 'time_increment_minutes', 'cleanup_buffer_minutes'] loop
    if jsonb_typeof(s -> field) is distinct from 'number' then
      raise exception 'LUXOR_WEEKDAY_INVALID: Missing numeric rental terms.' using errcode = 'P0001';
    end if;
  end loop;
  if s -> 'version' = '3'::jsonb then
    foreach field in array array['minimum_price', 'additional_hour_rate'] loop
      if jsonb_typeof(s -> field) is distinct from 'number' then
        raise exception 'LUXOR_WEEKDAY_INVALID: Missing version-3 pricing terms.' using errcode = 'P0001';
      end if;
    end loop;
  end if;
  if coalesce(s ->> 'event_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
     or coalesce(s ->> 'start_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     or coalesce(s ->> 'end_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    raise exception 'LUXOR_WEEKDAY_INVALID: Invalid saved rental date or times.' using errcode = 'P0001';
  end if;
  begin event_day := (s ->> 'event_date')::date;
  exception when datetime_field_overflow or invalid_datetime_format then
    raise exception 'LUXOR_WEEKDAY_INVALID: Invalid saved rental date.' using errcode = 'P0001';
  end;
  if extract(isodow from event_day) not between 1 and 4 then
    raise exception 'LUXOR_WEEKDAY_INVALID: Custom rentals require Monday through Thursday.' using errcode = 'P0001';
  end if;
  if (s ->> 'hourly_rate')::numeric <> 400
     or (s -> 'version' = '1'::jsonb and (
       (s ->> 'minimum_hours')::numeric <= 0 or (s ->> 'minimum_hours')::numeric > 19
       or abs((s ->> 'minimum_hours')::numeric * 60 - round((s ->> 'minimum_hours')::numeric * 60)) > 0.000000001
       or (s ->> 'time_increment_minutes')::numeric <= 0 or (s ->> 'time_increment_minutes')::numeric > 1140
       or mod((s ->> 'time_increment_minutes')::numeric, 1) <> 0
       or (s ->> 'cleanup_buffer_minutes')::numeric < 0 or (s ->> 'cleanup_buffer_minutes')::numeric > 1140
       or mod((s ->> 'cleanup_buffer_minutes')::numeric, 1) <> 0
       or coalesce(s ->> 'reset_window_policy', '') not in ('blocked', 'allowed')
       or coalesce(s ->> 'booking_policy', '') not in ('one_per_date', 'multiple_per_date')
       or coalesce(s ->> 'security_hours_policy', '') not in ('rental_duration', 'owner_entered')
       or coalesce(s ->> 'selection_surface', '') not in ('portal_only', 'public_and_portal')
     ))
     or (s -> 'version' = '2'::jsonb and (
       (s ->> 'minimum_hours')::numeric <> 3 or (s ->> 'time_increment_minutes')::numeric <> 60
       or (s ->> 'cleanup_buffer_minutes')::numeric <> 0
       or coalesce(s ->> 'reset_window_policy', '') <> 'allowed'
       or coalesce(s ->> 'booking_policy', '') <> 'one_per_date'
       or coalesce(s ->> 'security_hours_policy', '') <> 'arrival_to_end'
       or coalesce(s ->> 'selection_surface', '') <> 'portal_only'
     ))
     or (s -> 'version' = '3'::jsonb and (
       (s ->> 'minimum_hours')::numeric <> 3 or (s ->> 'time_increment_minutes')::numeric <> 60
       or (s ->> 'cleanup_buffer_minutes')::numeric <> 0
       or (s ->> 'minimum_price')::numeric <= 0
       or (s ->> 'additional_hour_rate')::numeric < 0
       or coalesce(s ->> 'reset_window_policy', '') <> 'allowed'
       or coalesce(s ->> 'booking_policy', '') <> 'one_per_date'
       or coalesce(s ->> 'security_hours_policy', '') <> 'arrival_to_end'
       or coalesce(s ->> 'selection_surface', '') <> 'portal_only'
     )) then
    raise exception 'LUXOR_WEEKDAY_INVALID: Incomplete approved rental policy.' using errcode = 'P0001';
  end if;
  first_min := split_part(s ->> 'start_time', ':', 1)::integer * 60 + split_part(s ->> 'start_time', ':', 2)::integer;
  last_min := split_part(s ->> 'end_time', ':', 1)::integer * 60 + split_part(s ->> 'end_time', ':', 2)::integer;
  if last_min < 360 then last_min := last_min + 1440; end if;
  duration_min := last_min - first_min;
  increment_min := (s ->> 'time_increment_minutes')::integer;
  if first_min < 360 or last_min > 1500 or duration_min <= 0
     or mod(first_min, increment_min) <> 0 or mod(last_min, increment_min) <> 0
     or (s -> 'version' in ('1'::jsonb, '2'::jsonb) and duration_min < round((s ->> 'minimum_hours')::numeric * 60))
     or (s -> 'version' = '1'::jsonb and s ->> 'reset_window_policy' = 'blocked' and first_min < 1020 and last_min > 900)
     or (s ->> 'duration_minutes')::numeric <> duration_min
     or abs((s ->> 'duration_hours')::numeric - duration_min::numeric / 60) > 0.000000001 then
    raise exception 'LUXOR_WEEKDAY_INVALID: Rental duration does not match the saved times.' using errcode = 'P0001';
  end if;
  if s -> 'version' = '3'::jsonb then
    expected_total := round((s ->> 'minimum_price')::numeric +
      greatest(0, duration_min::numeric / 60 - (s ->> 'minimum_hours')::numeric) * (s ->> 'additional_hour_rate')::numeric, 2);
  else
    expected_total := round(duration_min::numeric * 400 / 60, 2);
  end if;
  if (s ->> 'rental_total')::numeric <> expected_total then
    raise exception 'LUXOR_WEEKDAY_INVALID: Rental price does not match the frozen formula.' using errcode = 'P0001';
  end if;
  foreach field in array array['event_date', 'start_time', 'end_time'] loop
    if p_context ->> field is distinct from s ->> field then
      raise exception 'LUXOR_WEEKDAY_INVALID: Canonical rental timing does not match its snapshot.' using errcode = 'P0001';
    end if;
  end loop;
  if s -> 'version' = '3'::jsonb then
    if (p_context ? 'rental_start_time' and p_context ->> 'rental_start_time' is distinct from s ->> 'start_time')
       or (p_context ? 'rental_end_time' and p_context ->> 'rental_end_time' is distinct from s ->> 'end_time') then
      raise exception 'LUXOR_WEEKDAY_INVALID: Canonical rental boundaries conflict with the snapshot.' using errcode = 'P0001';
    end if;
    if coalesce(p_context ->> 'guest_arrival_time', p_context ->> 'guestArrivalTime', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or coalesce(p_context ->> 'event_end_time', p_context ->> 'eventEndTime', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      raise exception 'LUXOR_WEEKDAY_INVALID: Guest arrival and event end are required.' using errcode = 'P0001';
    end if;
    arrival_min := split_part(coalesce(p_context ->> 'guest_arrival_time', p_context ->> 'guestArrivalTime'), ':', 1)::integer * 60
      + split_part(coalesce(p_context ->> 'guest_arrival_time', p_context ->> 'guestArrivalTime'), ':', 2)::integer;
    event_end_min := split_part(coalesce(p_context ->> 'event_end_time', p_context ->> 'eventEndTime'), ':', 1)::integer * 60
      + split_part(coalesce(p_context ->> 'event_end_time', p_context ->> 'eventEndTime'), ':', 2)::integer;
    if arrival_min < 360 then arrival_min := arrival_min + 1440; end if;
    if event_end_min < 360 then event_end_min := event_end_min + 1440; end if;
    if arrival_min < first_min or arrival_min > last_min or event_end_min < arrival_min or event_end_min > last_min then
      raise exception 'LUXOR_WEEKDAY_INVALID: Guest arrival and event end must fall within rental boundaries.' using errcode = 'P0001';
    end if;
  elsif (p_context ? 'guest_arrival_time' and p_context ->> 'guest_arrival_time' is distinct from s ->> 'start_time')
     or (p_context ? 'guestArrivalTime' and p_context ->> 'guestArrivalTime' is distinct from s ->> 'start_time')
     or (p_context ? 'event_end_time' and p_context ->> 'event_end_time' is distinct from s ->> 'end_time')
     or (p_context ? 'eventEndTime' and p_context ->> 'eventEndTime' is distinct from s ->> 'end_time') then
    raise exception 'LUXOR_WEEKDAY_INVALID: Display timing conflicts with the canonical rental.' using errcode = 'P0001';
  end if;
  policy := coalesce(
    p_context #> '{pricing_snapshot,pricing_config,luxor_costs,weekday_custom_rental}',
    p_context #> '{pricing_snapshot,pricing_config,weekday_custom_rental}'
  );
  if jsonb_typeof(policy) is distinct from 'object' or policy -> 'enabled' is distinct from 'true'::jsonb then
    raise exception 'LUXOR_WEEKDAY_INVALID: The frozen pricing policy is unavailable.' using errcode = 'P0001';
  end if;
  foreach field in array array['hourly_rate', 'minimum_hours', 'time_increment_minutes', 'cleanup_buffer_minutes'] loop
    if coalesce(jsonb_typeof(policy -> field), '') not in ('number', 'string') then
      raise exception 'LUXOR_WEEKDAY_INVALID: The frozen numeric policy is unavailable.' using errcode = 'P0001';
    end if;
    begin
      if (policy ->> field)::numeric is distinct from (s ->> field)::numeric then
        raise exception 'LUXOR_WEEKDAY_INVALID: Rental policy differs from the frozen approved catalog.' using errcode = 'P0001';
      end if;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'LUXOR_WEEKDAY_INVALID: The frozen numeric policy is invalid.' using errcode = 'P0001';
    end;
  end loop;
  if s -> 'version' = '3'::jsonb then
    foreach field in array array['minimum_price', 'additional_hour_rate'] loop
      if coalesce(jsonb_typeof(policy -> field), '') not in ('number', 'string')
         or (policy ->> field)::numeric is distinct from (s ->> field)::numeric then
        raise exception 'LUXOR_WEEKDAY_INVALID: Rental price differs from the frozen catalog.' using errcode = 'P0001';
      end if;
    end loop;
  end if;
  foreach field in array array['reset_window_policy', 'booking_policy', 'security_hours_policy', 'selection_surface'] loop
    if policy -> field is distinct from s -> field then
      raise exception 'LUXOR_WEEKDAY_INVALID: Rental policy differs from the frozen approved catalog.' using errcode = 'P0001';
    end if;
  end loop;
  return s;
end;
$$;

-- First-send numbers are committed only after the provider accepts the send.
create or replace function public.luxor_claim_weekday_proposal_acceptance(
  p_invoice_id uuid,
  p_booking jsonb,
  p_accepted_at timestamptz,
  p_ip text default null,
  p_user_agent text default null
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  invoice public.luxor_invoices%rowtype;
  booking public.luxor_bookings%rowtype;
  proposed public.luxor_bookings%rowtype;
  snapshot jsonb;
  guest_count integer;
  field text;
  accepted_at timestamptz := coalesce(p_accepted_at, now());
begin
  select i.* into invoice from public.luxor_invoices i where i.id = p_invoice_id for update;
  if not found or invoice.invoice_kind is distinct from 'event' or invoice.status is distinct from 'sent'
     or invoice.price_locked_at is null or invoice.offer_status = 'withdrawn' or invoice.inquiry_id is null then
    raise exception 'LUXOR_WEEKDAY_INVALID: A published active locked proposal is required.' using errcode = 'P0001';
  end if;
  snapshot := public.luxor_validate_weekday_rental_context(invoice.proposal_context);
  if snapshot is null then raise exception 'LUXOR_WEEKDAY_INVALID: A saved custom rental is required.' using errcode = 'P0001'; end if;
  if snapshot -> 'version' not in ('2'::jsonb, '3'::jsonb) then
    raise exception 'LUXOR_WEEKDAY_INVALID: Historical custom rental terms require administrator review before acceptance.' using errcode = 'P0001';
  end if;
  -- This SECURITY INVOKER RPC is executable only by service_role. The
  -- application checks LUXOR_WEEKDAY_CUSTOM_RENTAL_V3_BOOKING_GUARD_READY
  -- before calling it, matching the pre-existing versioned acceptance path.
  if exists(select 1 from public.luxor_inquiries q where q.id = invoice.inquiry_id and q.status = 'closed_lost') then
    raise exception 'LUXOR_WEEKDAY_INVALID: The client opportunity is closed.' using errcode = 'P0001';
  end if;
  select b.* into booking from public.luxor_bookings b where b.invoice_id = invoice.id;
  if found and invoice.proposal_accepted_at is not null then
    if invoice.booking_id is distinct from booking.id then
      raise exception 'LUXOR_WEEKDAY_INVALID: Existing proposal and booking links require review.' using errcode = 'P0001';
    end if;
    return to_jsonb(invoice);
  end if;
  if not exists (
    select 1 from pg_catalog.pg_trigger t
    where t.tgrelid = 'public.luxor_bookings'::regclass and t.tgname = 'luxor_weekday_booking_schedule_guard'
      and t.tgenabled = 'O' and t.tgfoid = 'public.luxor_guard_weekday_booking_schedule()'::regprocedure
  ) then raise exception 'LUXOR_WEEKDAY_INVALID: The scheduling guard is unavailable.' using errcode = 'P0001'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'LUXOR_WEEKDAY_INVALID: Scheduling writes require READ COMMITTED isolation.' using errcode = 'P0001';
  end if;
  if invoice.offer_expires_at is not null and invoice.offer_expires_at <= now() then
    raise exception 'LUXOR_WEEKDAY_INVALID: The proposal has expired.' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_booking) is distinct from 'object' then raise exception 'LUXOR_WEEKDAY_INVALID: Booking facts are required.' using errcode = 'P0001'; end if;
  proposed := jsonb_populate_record(null::public.luxor_bookings, p_booking);
  foreach field in array array['final_event_price', 'amount_due_to_book', 'refundable_security_deposit'] loop
    if jsonb_typeof(invoice.proposal_context -> field) is distinct from 'number' then
      raise exception 'LUXOR_WEEKDAY_INVALID: Locked financial terms are required.' using errcode = 'P0001';
    end if;
  end loop;
  if invoice.total is null or invoice.total <= 0 or proposed.contract_total is null
     or proposed.deposit_required is null or proposed.security_deposit_amount is null then
    raise exception 'LUXOR_WEEKDAY_INVALID: Valid booking amounts are required.' using errcode = 'P0001';
  end if;
  if jsonb_typeof(invoice.proposal_context -> 'expected_guest_count') is distinct from 'number'
     or (invoice.proposal_context ->> 'expected_guest_count')::numeric not between 1 and 200
     or mod((invoice.proposal_context ->> 'expected_guest_count')::numeric, 1) <> 0 then
    raise exception 'LUXOR_WEEKDAY_INVALID: A valid guest count is required.' using errcode = 'P0001';
  end if;
  guest_count := (invoice.proposal_context ->> 'expected_guest_count')::integer;
  if proposed.invoice_id is distinct from invoice.id or proposed.inquiry_id is distinct from invoice.inquiry_id
     or proposed.lead_event_id is distinct from invoice.lead_event_id or proposed.client_name is distinct from invoice.client_name
     or proposed.event_date::text is distinct from snapshot ->> 'event_date'
     or proposed.start_time is null or proposed.end_time is null
     or proposed.start_time::time is distinct from (snapshot ->> 'start_time')::time
     or proposed.end_time::time is distinct from (snapshot ->> 'end_time')::time
     or proposed.guest_count is distinct from guest_count
     or proposed.status is distinct from 'tentative' or proposed.contract_status is distinct from 'not_sent'
     or proposed.security_deposit_status is distinct from 'due'
     or proposed.contract_total is distinct from invoice.total
     or proposed.contract_total is distinct from (invoice.proposal_context ->> 'final_event_price')::numeric
     or proposed.deposit_required is distinct from (invoice.proposal_context ->> 'amount_due_to_book')::numeric
     or proposed.deposit_required < 0.5 or proposed.deposit_required > proposed.contract_total
     or proposed.security_deposit_amount is distinct from (invoice.proposal_context ->> 'refundable_security_deposit')::numeric
     or proposed.security_deposit_amount is distinct from 750::numeric
     or proposed.metadata -> 'final_proposal_context' is distinct from invoice.proposal_context then
    raise exception 'LUXOR_WEEKDAY_INVALID: Booking facts differ from the locked proposal.' using errcode = 'P0001';
  end if;
  if booking.id is not null then raise exception 'LUXOR_WEEKDAY_INVALID: A booking without acceptance requires administrator review.' using errcode = 'P0001'; end if;
  insert into public.luxor_bookings (
    inquiry_id, invoice_id, lead_event_id, client_name, email, phone, event_type,
    event_date, start_time, end_time, guest_count, package_name, status, booked_at,
    contract_total, deposit_required, security_deposit_amount, final_payment_due_date,
    contract_status, security_deposit_status, notes, metadata
  ) values (
    proposed.inquiry_id, proposed.invoice_id, proposed.lead_event_id, proposed.client_name,
    proposed.email, proposed.phone, proposed.event_type, proposed.event_date, proposed.start_time,
    proposed.end_time, proposed.guest_count, proposed.package_name, proposed.status, accepted_at,
    proposed.contract_total, proposed.deposit_required, proposed.security_deposit_amount,
    proposed.final_payment_due_date, proposed.contract_status, proposed.security_deposit_status,
    proposed.notes, proposed.metadata
  ) returning * into booking;
  update public.luxor_invoices i set proposal_accepted_at = coalesce(i.proposal_accepted_at, accepted_at),
    proposal_accepted_ip = case when i.proposal_accepted_at is null then left(p_ip, 128) else i.proposal_accepted_ip end,
    proposal_accepted_user_agent = case when i.proposal_accepted_at is null then left(p_user_agent, 1000) else i.proposal_accepted_user_agent end,
    booking_id = booking.id, offer_status = 'active', updated_at = now()
  where i.id = invoice.id returning i.* into invoice;
  return to_jsonb(invoice);
end;
$$;

revoke all on function public.luxor_reject_proposal_activity_mutation() from public, anon, authenticated;
revoke all on function public.luxor_assign_proposal_family() from public, anon, authenticated;
revoke all on function public.luxor_proposal_activity_trigger() from public, anon, authenticated;
revoke all on function public.luxor_append_proposal_activity(uuid, text, text, text, text, text, text, timestamptz, text, jsonb) from public, anon, authenticated;
revoke all on function public.luxor_begin_proposal_send(uuid, uuid, text, text, text, text) from public, anon, authenticated;
revoke all on function public.luxor_complete_proposal_send(uuid, text, timestamptz) from public, anon, authenticated;
revoke all on function public.luxor_mark_proposal_send_attempt_sending(uuid) from public, anon, authenticated;
revoke all on function public.luxor_fail_proposal_send(uuid, text, boolean, timestamptz) from public, anon, authenticated;
